        var publicMovies by remember { mutableStateOf<List<AnimeBrief>>(emptyList()) }
        var publicMoviesLoading by remember { mutableStateOf(false) }
        val publicFranchises = remember {
            listOf(
                "Doraemon",
                "Crayon Shin-chan",
                "Pokemon",
                "Detective Conan",
                "Dragon Ball",
                "Naruto",
                "Demon Slayer",
                "That Time I Got Reincarnated as a Slime",
