                                    if (libraryItemsList.isNotEmpty()) {
                                        Text(
                                            text = "${filteredLibraryItems.size} Titles",
                                            fontSize = 12.sp,
                                            color = primaryColor,
                                            fontWeight = FontWeight.Medium
