                                                                isSubtitleToolExpanded = !isSubtitleToolExpanded
                                                            }
                                                            .padding(vertical = 4.dp)
                                                    ) {
                                                        androidx.compose.foundation.Image(
                                                            painter = painterResource(R.drawable.ic_ml_kit_logo),
                                                            contentDescription = "Subtitle Tool",
                                                            modifier = Modifier.height(24.dp)
                                                        )
                                                        Spacer(modifier = Modifier.width(12.dp))
                                                        Column(modifier = Modifier.weight(1f)) {
                                                            Text(
                                                                text = "Subtitle Translator Model",
                                                                color = Color.White,
                                                                fontSize = 15.sp,
                                                                fontWeight = FontWeight.Bold
                                                            )
                                                            Text(
                                                                text = "$totalDownloadedInTier of ${currentTierList.size} ${if (selectedSubTier == "pro") "Pro" else "Normal"} Models Downloaded",
                                                                color = Color(0xFF9E9EA4),
                                                                fontSize = 12.sp
                                                            )
                                                        }
                                                        Icon(
                                                            imageVector = if (isSubtitleToolExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                                            contentDescription = if (isSubtitleToolExpanded) "Collapse" else "Expand",
                                                            tint = Color(0xFF8E8E93),
                                                            modifier = Modifier.size(24.dp)
                                                        )
                                                    }

                                                    if (isSubtitleToolExpanded || isSubModelDownloading) {
                                                        Spacer(modifier = Modifier.height(12.dp))

                                                        // Dual Tier Selector: Normal (Fast) vs Pro (Deep Neural)
                                                        if (com.lagradost.cloudstream3.BuildConfig.SHOW_PRO_MODELS) {
                                                            Row(
                                                                modifier = Modifier
                                                                    .fillMaxWidth()
                                                                    .clip(RoundedCornerShape(8.dp))
                                                                    .background(Color(0xFF1B1B20))
                                                                    .padding(3.dp),
                                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                            ) {
                                                                Box(
                                                                    modifier = Modifier
                                                                        .weight(1f)
                                                                        .clip(RoundedCornerShape(6.dp))
                                                                        .background(if (selectedSubTier == "normal") Color.White else Color.Transparent)
                                                                        .clickable {
                                                                            selectedSubTier = "normal"
                                                                            com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.setSelectedTranslationTier(this@AnimeBoxMainActivity, "normal")
                                                                        }
                                                                        .padding(vertical = 6.dp),
                                                                    contentAlignment = Alignment.Center
                                                                ) {
                                                                    Text(
                                                                        text = "Normal (Fast ~30MB)",
                                                                        color = if (selectedSubTier == "normal") Color.Black else Color(0xFF9E9EA4),
                                                                        fontSize = 12.sp,
                                                                        fontWeight = if (selectedSubTier == "normal") FontWeight.Bold else FontWeight.Medium
                                                                    )
                                                                }

                                                                Box(
                                                                    modifier = Modifier
                                                                        .weight(1f)
                                                                        .clip(RoundedCornerShape(6.dp))
                                                                        .background(if (selectedSubTier == "pro") Color.White else Color.Transparent)
                                                                        .clickable {
                                                                            selectedSubTier = "pro"
                                                                            com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.setSelectedTranslationTier(this@AnimeBoxMainActivity, "pro")
                                                                        }
                                                                        .padding(vertical = 6.dp),
                                                                    contentAlignment = Alignment.Center
                                                                ) {
                                                                    Text(
                                                                        text = "Pro (High Accuracy)",
                                                                        color = if (selectedSubTier == "pro") Color.Black else Color(0xFF9E9EA4),
                                                                        fontSize = 12.sp,
                                                                        fontWeight = if (selectedSubTier == "pro") FontWeight.Bold else FontWeight.Medium
                                                                    )
                                                                }
                                                            }
                                                            Spacer(modifier = Modifier.height(10.dp))
                                                        }

                                                        // Active Download Progress inside Tool if downloading subtitle translation model
                                                        if (isSubModelDownloading) {
                                                            activeAiModelProgress?.let { dlProgress ->
                                                                Column(
                                                                    modifier = Modifier
                                                                        .fillMaxWidth()
                                                                        .padding(bottom = 8.dp)
                                                                        .clip(RoundedCornerShape(6.dp))
                                                                        .background(Color(0xFF1E1E24))
                                                                        .padding(horizontal = 12.dp, vertical = 8.dp)
                                                                ) {
                                                                    Row(
                                                                        modifier = Modifier.fillMaxWidth(),
                                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                                        verticalAlignment = Alignment.CenterVertically
                                                                    ) {
                                                                        Text(
                                                                            text = "Downloading ${dlProgress.langName}...",
                                                                            color = Color.White,
                                                                            fontSize = 13.sp,
                                                                            fontWeight = FontWeight.SemiBold
                                                                        )
                                                                        Text(
                                                                            text = "${dlProgress.percent}%",
                                                                            color = Color(0xFFA0A0AA),
                                                                            fontSize = 12.sp,
                                                                            fontWeight = FontWeight.Bold
                                                                        )
                                                                    }
                                                                    Spacer(modifier = Modifier.height(4.dp))
                                                                    Box(
                                                                        modifier = Modifier
                                                                            .fillMaxWidth()
                                                                            .height(3.dp)
                                                                            .clip(RoundedCornerShape(2.dp))
                                                                            .background(Color(0xFF2E2E38))
                                                                    ) {
                                                                        Box(
                                                                            modifier = Modifier
                                                                                .fillMaxWidth((dlProgress.percent / 100f).coerceIn(0f, 1f))
                                                                                .fillMaxHeight()
                                                                                .clip(RoundedCornerShape(2.dp))
                                                                                .background(Color.White)
                                                                        )
                                                                    }
                                                                }
                                                            }
                                                        }

                                                        // Language list inside Subtitle Tool
                                                        Column(
                                                            modifier = Modifier.fillMaxWidth(),
                                                            verticalArrangement = Arrangement.spacedBy(6.dp)
                                                        ) {
                                                            currentTierList.forEach { langModel ->
                                                                val isDownloaded = installedAiModels.any { it.langCode.equals(langModel.langCode, true) }
                                                                val isCurrentlyDownloading = activeAiModelProgress?.langCode?.equals(langModel.langCode, true) == true
                                                                val sizeMb = langModel.sizeBytes / (1024 * 1024)

                                                                Row(
                                                                    modifier = Modifier
                                                                        .fillMaxWidth()
                                                                        .clip(RoundedCornerShape(6.dp))
                                                                        .background(Color(0xFF1B1B1F))
                                                                        .padding(horizontal = 12.dp, vertical = 7.dp),
                                                                    verticalAlignment = Alignment.CenterVertically,
                                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                                ) {
                                                                    Column(modifier = Modifier.weight(1f)) {
                                                                        Text(
                                                                            text = langModel.langName,
                                                                            color = Color.White,
                                                                            fontSize = 13.5.sp,
                                                                            fontWeight = FontWeight.Medium
                                                                        )
                                                                        Text(
                                                                            text = "${sizeMb} MB",
                                                                            color = Color(0xFF8E8E93),
                                                                            fontSize = 11.sp
                                                                        )
                                                                    }

                                                                    if (isCurrentlyDownloading) {
                                                                        Text(
                                                                            text = "${activeAiModelProgress?.percent ?: 0}%",
                                                                            color = Color.White,
                                                                            fontSize = 12.sp,
                                                                            fontWeight = FontWeight.SemiBold
                                                                        )
                                                                    } else if (isDownloaded) {
                                                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                                                            Box(
                                                                                modifier = Modifier
                                                                                    .clip(RoundedCornerShape(8.dp))
                                                                                    .background(Color(0xFF2E7D32).copy(alpha = 0.25f))
                                                                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                                                                            ) {
                                                                                Text(
                                                                                    text = if (selectedSubTier == "pro") "PRO READY" else "INSTALLED",
                                                                                    color = Color(0xFF81C784),
                                                                                    fontSize = 9.5.sp,
                                                                                    fontWeight = FontWeight.Bold
                                                                                )
                                                                            }
                                                                            Spacer(modifier = Modifier.width(6.dp))
                                                                            IconButton(
                                                                                onClick = { modelToDelete = langModel },
                                                                                modifier = Modifier.size(28.dp)
                                                                            ) {
                                                                                Icon(
                                                                                    imageVector = NetflixDustbinIcon,
                                                                                    contentDescription = "Delete Model",
                                                                                    tint = Color(0xFFF7A877),
                                                                                    modifier = Modifier.size(17.dp)
                                                                                )
                                                                            }
                                                                        }
                                                                    } else {
                                                                        IconButton(
                                                                            onClick = {
                                                                                startDirectModelDownload(langModel, false)
                                                                            },
                                                                            modifier = Modifier.size(28.dp)
                                                                        ) {
                                                                            Icon(
                                                                                imageVector = CloudDownloadIcon,
                                                                                contentDescription = "Download Model",
                                                                                tint = Color.White,
                                                                                modifier = Modifier.size(18.dp)
                                                                            )
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    } else if (selectedDownloadFilter == "Screenshots") {
                                        ScreenshotsDownloadSection(
                                            screenshotGroups = screenshotGroups,
                                            dQuery = dQuery,
                                            downloadManager = downloadManager,
                                            onSelectScreenshot = { list, idx ->
                                                fullscreenScreenshotGallery = Pair(list, idx)
                                            },
                                            onScreenshotDeleted = { screenshotRefreshRevision++ },
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .weight(1f)
                                        )
                                    } else if (activeDownloads.isEmpty() && completedVideos.isEmpty()) {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .weight(1f),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Column(
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.Center,
                                                modifier = Modifier.padding(24.dp)
                                            ) {
                                                Icon(
                                                    imageVector = CustomDownloadsNavbarIcon,
                                                    contentDescription = "Downloads",
                                                    tint = Color(0xFF8E8E93),
                                                    modifier = Modifier.size(64.dp)
                                                )
                                                Spacer(modifier = Modifier.height(18.dp))
                                                Text(
                                                    text = if (downloadSearchQuery.isNotEmpty()) "No Downloads Found" else "Your offline library starts here",
                                                    fontSize = 19.sp,
                                                    fontWeight = FontWeight.Normal,
                                                    color = Color.White
                                                )
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text(
                                                    text = if (downloadSearchQuery.isNotEmpty()) "Try searching with a different title." else "Download episodes to watch without internet. Firefly keeps each anime together and orders episodes by number.",
                                                    fontSize = 13.sp,
                                                    color = Color(0xFF9E9EA4),
                                                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                                    lineHeight = 18.sp,
                                                    modifier = Modifier.fillMaxWidth(0.85f)
                                                )
                                                if (downloadSearchQuery.isEmpty()) {
                                                    Spacer(modifier = Modifier.height(20.dp))
                                                    Button(
                                                        onClick = onExploreClick,
                                                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary, contentColor = Color(0xFF141414)),
                                                        shape = RoundedCornerShape(24.dp),
                                                        contentPadding = PaddingValues(horizontal = 22.dp, vertical = 10.dp)
                                                    ) {
                                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                                            Icon(
                                                                imageVector = CustomSearchIcon,
                                                                contentDescription = null,
                                                                tint = Color(0xFF141414),
                                                                modifier = Modifier.size(17.dp)
                                                            )
                                                            Spacer(modifier = Modifier.width(6.dp))
                                                            Text(
                                                                text = "Find anime to download",
                                                                fontSize = 13.5.sp,
                                                                fontWeight = FontWeight.Medium,
                                                                color = Color(0xFF141414)
                                                            )
                                                        }
                                                    }
                                                    Spacer(modifier = Modifier.height(28.dp))
                                                    Card(
                                                        shape = RoundedCornerShape(12.dp),
                                                        colors = CardDefaults.cardColors(containerColor = Color(0xFF141414)),
                                                        modifier = Modifier.fillMaxWidth(0.92f)
                                                    ) {
                                                        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
                                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                                Icon(
                                                                    imageVector = SolarFolderWithFilesVector,
                                                                    contentDescription = null,
                                                                    tint = Color(0xFF9E9EA4),
                                                                    modifier = Modifier.size(22.dp)
                                                                )
                                                                Spacer(modifier = Modifier.width(14.dp))
                                                                Column {
                                                                    Text("Organized automatically", color = Color.White, fontSize = 13.5.sp, fontWeight = FontWeight.Normal)
                                                                    Text("Episodes are grouped into anime folders.", color = Color(0xFF8E8E93), fontSize = 11.5.sp)
                                                                }
                                                            }
                                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                                Icon(
                                                                    imageVector = SolarPlayCircleVector,
                                                                    contentDescription = null,
                                                                    tint = Color(0xFF9E9EA4),
                                                                    modifier = Modifier.size(22.dp)
                                                                )
                                                                Spacer(modifier = Modifier.width(14.dp))
                                                                Column {
                                                                    Text("Same Firefly player", color = Color.White, fontSize = 13.5.sp, fontWeight = FontWeight.Normal)
                                                                    Text("Offline and online playback use the same controls.", color = Color(0xFF8E8E93), fontSize = 11.5.sp)
                                                                }
                                                            }
                                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                                Icon(
                                                                    imageVector = SolarSubtitlesVector,
                                                                    contentDescription = null,
                                                                    tint = Color(0xFF9E9EA4),
                                                                    modifier = Modifier.size(22.dp)
                                                                )
                                                                Spacer(modifier = Modifier.width(14.dp))
                                                                Column {
                                                                    Text("Audio and subtitles", color = Color.White, fontSize = 13.5.sp, fontWeight = FontWeight.Normal)
                                                                    Text("Choose language, quality, and subtitles before downloading.", color = Color(0xFF8E8E93), fontSize = 11.5.sp)
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    } else {
                                        LazyColumn(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .weight(1f),
                                            verticalArrangement = Arrangement.spacedBy(8.dp),
                                            contentPadding = PaddingValues(bottom = 24.dp)
                                        ) {
                                            // Active in-progress downloads
                                            if (activeDownloads.isNotEmpty() && selectedDownloadFilter != "Series") {
                                                item {
                                                    Text(
                                                        text = "Active Downloads (${activeDownloads.size})",
                                                        fontSize = 13.5.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = Color.White,
                                                        modifier = Modifier.padding(top = 4.dp, bottom = 2.dp)
                                                    )
                                                }
                                                items(activeDownloads, key = { it.id }) { downloadingEp ->
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clip(RoundedCornerShape(6.dp))
                                                            .background(Color(0xFF141414))
                                                            .padding(10.dp),
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Box(
                                                            modifier = Modifier
                                                                .width(128.dp)
                                                                .height(72.dp)
                                                                .clip(RoundedCornerShape(5.dp))
                                                                .background(Color(0xFF1E1E1E)),
                                                            contentAlignment = Alignment.Center
                                                        ) {
                                                            if (downloadingEp.coverUrl.isNotEmpty()) {
                                                                Image(
                                                                    painter = rememberAsyncImagePainter(model = resolveImageModel(downloadingEp.coverUrl)),
                                                                    contentDescription = downloadingEp.animeTitle,
                                                                    contentScale = ContentScale.Crop,
                                                                    modifier = Modifier.fillMaxSize()
                                                                )
                                                                Box(
                                                                    modifier = Modifier
                                                                        .fillMaxSize()
                                                                        .background(Color.Black.copy(alpha = 0.55f))
                                                                )
                                                            }
                                                            CircularProgressIndicator(
                                                                progress = (downloadingEp.downloadProgress / 100f).coerceIn(0f, 1f),
                                                                color = Color.White,
                                                                strokeWidth = 2.5.dp,
                                                                modifier = Modifier.size(24.dp)
                                                            )
                                                        }
                                                        Spacer(modifier = Modifier.width(12.dp))
                                                        Column(modifier = Modifier.weight(1f)) {
                                                            Text(
                                                                text = downloadingEp.animeTitle,
                                                                color = Color.White,
                                                                fontSize = 15.sp,
                                                                fontWeight = FontWeight.SemiBold,
                                                                maxLines = 1,
                                                                overflow = TextOverflow.Ellipsis
                                                            )
                                                            Spacer(modifier = Modifier.height(2.dp))
                                                            Text(
                                                                text = "Episode ${downloadingEp.episodeNumber} • ${downloadingEp.downloadProgress}% • ${downloadingEp.downloadSpeedText}",
                                                                color = Color(0xFF9E9EA4),
                                                                fontSize = 12.sp
                                                            )
                                                        }
                                                        IconButton(
                                                            onClick = {
                                                                coroutineScope.launch {
                                                                    downloadManager.cancelDownload(downloadingEp.anilistId, downloadingEp.episodeNumber)
                                                                }
                                                            },
                                                            modifier = Modifier.size(32.dp)
                                                        ) {
                                                            Icon(
                                                                imageVector = Icons.Default.Close,
                                                                contentDescription = "Cancel",
                                                                tint = Color.White,
                                                                modifier = Modifier.size(18.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            // DOWNLOADED ANIME / MOVIE CARDS (16:9 Backdrop + Show Logo + White Phone Icon)
                                            if (downloadedGroups.isNotEmpty() && selectedDownloadFilter != "Downloading") {
                                                items(downloadedGroups, key = { if (it.anilistId > 0) "series_${it.anilistId}" else "series_${it.animeTitle.trim().lowercase()}" }) { group ->
                                                    val isSingleVideo = group.episodes.size == 1
                                                    var backdropUrl by remember(group.anilistId) { mutableStateOf(group.backdropUrl) }
                                                    var logoUrl by remember(group.anilistId) { mutableStateOf(group.logoUrl) }

                                                    LaunchedEffect(group.anilistId) {
                                                        if (backdropUrl.isEmpty()) {
                                                            val bg = AniZipClient.getAnimeBackdropUrl(group.anilistId)
                                                            if (bg.isNotEmpty()) backdropUrl = bg
                                                        }
                                                        if (logoUrl.isEmpty()) {
                                                            val logo = AniZipClient.getAnimeLogoUrl(group.anilistId)
                                                            if (logo.isNotEmpty()) logoUrl = logo
                                                        }
                                                    }

                                                    val displayImage = group.backdropUrl.ifEmpty { backdropUrl.ifEmpty { group.coverUrl } }
                                                    val displayLogo = group.logoUrl.ifEmpty { logoUrl }

                                                    var isDeleteOverlayActive by remember { mutableStateOf(false) }

                                                    Box(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clip(RoundedCornerShape(6.dp))
                                                            .background(Color.Transparent)
                                                            .pointerInput(isSingleVideo, isDeleteOverlayActive) {
                                                                detectTapGestures(
                                                                    onLongPress = {
                                                                        if (isSingleVideo) {
                                                                            isDeleteOverlayActive = !isDeleteOverlayActive
                                                                        }
                                                                    },
                                                                    onTap = {
                                                                        if (isDeleteOverlayActive) {
                                                                            isDeleteOverlayActive = false
                                                                        } else if (isSingleVideo) {
                                                                            group.episodes.firstOrNull()?.let { playEpisode(it) }
                                                                        } else {
                                                                            selectedSeriesDrilldown = group
                                                                        }
                                                                    }
                                                                )
                                                            }
                                                    ) {
                                                        Row(
                                                            modifier = Modifier
                                                                .fillMaxWidth()
                                                                .padding(vertical = 6.dp),
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                        // 16:9 Backdrop Thumbnail
                                                        Box(
                                                            modifier = Modifier
                                                                .width(132.dp)
                                                                .height(74.dp)
                                                                .clip(RoundedCornerShape(5.dp))
                                                                .background(Color(0xFF1E1E1E)),
                                                            contentAlignment = Alignment.Center
                                                        ) {
                                                            Image(
                                                                painter = rememberAsyncImagePainter(model = resolveImageModel(displayImage)),
                                                                contentDescription = group.animeTitle,
                                                                contentScale = ContentScale.Crop,
                                                                modifier = Modifier.fillMaxSize()
                                                            )

                                                            // Dark gradient overlay
                                                            Box(
                                                                modifier = Modifier
                                                                    .fillMaxSize()
                                                                    .background(
                                                                        Brush.verticalGradient(
                                                                            colors = listOf(
                                                                                Color.Black.copy(alpha = 0.15f),
                                                                                Color.Black.copy(alpha = 0.65f)
                                                                            )
                                                                        )
                                                                    )
                                                            )

                                                            // FireFly App Logo in top left (a little big)
                                                            Box(
                                                                modifier = Modifier
                                                                    .align(Alignment.TopStart)
                                                                    .padding(start = 5.dp, top = 4.dp)
                                                            ) {
                                                                Image(
                                                                    painter = painterResource(id = R.drawable.firefly_logo),
                                                                    contentDescription = "FireFly",
                                                                    modifier = Modifier
                                                                        .height(17.dp)
                                                                        .wrapContentWidth(),
                                                                    contentScale = ContentScale.Fit
                                                                )
                                                            }

                                                            // Show Logo Overlay (a little big)
                                                            if (displayLogo.isNotEmpty()) {
                                                                Image(
                                                                    painter = rememberAsyncImagePainter(model = resolveImageModel(displayLogo)),
                                                                    contentDescription = "Logo",
                                                                    contentScale = ContentScale.Fit,
                                                                    modifier = Modifier
                                                                        .align(Alignment.BottomStart)
                                                                        .padding(start = 5.dp, bottom = 4.dp, end = 5.dp)
                                                                        .height(28.dp)
                                                                        .fillMaxWidth(0.85f)
                                                                )
                                                            }

                                                            // If single video, center play button
                                                            if (isSingleVideo) {
                                                                Box(
                                                                    modifier = Modifier
                                                                        .size(28.dp)
                                                                        .align(Alignment.Center)
                                                                        .background(Color.Black.copy(alpha = 0.60f), CircleShape)
                                                                        .border(1.dp, Color.White.copy(alpha = 0.85f), CircleShape),
                                                                    contentAlignment = Alignment.Center
                                                                ) {
                                                                    Icon(
                                                                        imageVector = SolarPlayVector,
                                                                        contentDescription = "Play",
                                                                        tint = Color.White,
                                                                        modifier = Modifier.size(17.dp)
                                                                    )
                                                                }
                                                            }
                                                        }

                                                        Spacer(modifier = Modifier.width(14.dp))

                                                        // Middle: Title & Metadata Line
                                                        Column(modifier = Modifier.weight(1f)) {
                                                            Text(
                                                                text = group.animeTitle,
                                                                color = Color.White,
                                                                fontSize = 15.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                maxLines = 2,
                                                                overflow = TextOverflow.Ellipsis,
                                                                lineHeight = 18.sp
                                                            )
                                                            Spacer(modifier = Modifier.height(3.dp))
                                                            val distinctLangs = group.episodes.map { ep ->
                                                                when (ep.streamType.lowercase()) {
                                                                    "hindi" -> "Hindi"
                                                                    "dub" -> "Dub"
                                                                    "hardsub" -> "HSub"
                                                                    else -> "Sub"
                                                                }
                                                            }.distinct()
                                                            val hasMultiLangForSameEp = group.episodes.groupBy { it.episodeNumber }.any { it.value.map { e -> e.streamType.lowercase() }.distinct().size > 1 }
                                                            val langLabel = if (hasMultiLangForSameEp || distinctLangs.size > 1) "Multi" else (distinctLangs.firstOrNull() ?: "Sub")
                                                            val metaText = if (isSingleVideo) {
                                                                val singleEp = group.episodes.firstOrNull()
                                                                val epLangs = group.episodes.filter { it.episodeNumber == singleEp?.episodeNumber }.map { it.streamType.lowercase() }.distinct()
                                                                val q = if (epLangs.size > 1) "1080p Multi" else (singleEp?.quality ?: "HD")
                                                                "$q | ${formatDownloadedBytes(group.totalSizeBytes)}"
                                                            } else {
                                                                "${group.episodes.size} ${if (group.episodes.size == 1) "Episode" else "Episodes"} • $langLabel | ${formatDownloadedBytes(group.totalSizeBytes)}"
                                                            }
                                                            Text(
                                                                text = metaText,
                                                                color = Color(0xFF8E8E93),
                                                                fontSize = 12.5.sp,
                                                                fontWeight = FontWeight.Normal
                                                            )
                                                        }

                                                        Spacer(modifier = Modifier.width(8.dp))

                                                        // Right: Chevron for series, or Clean White Phone Checkmark for single download
                                                        if (isSingleVideo) {
                                                            NetflixDownloadedPhoneIcon(
                                                                modifier = Modifier
                                                                    .size(24.dp)
                                                                    .clickable { isDeleteOverlayActive = !isDeleteOverlayActive },
                                                                tint = Color.White
                                                            )
                                                        } else {
                                                            Icon(
                                                                imageVector = Icons.AutoMirrored.Filled.KeyboardArrowRight,
                                                                contentDescription = "Open Series",
                                                                tint = Color(0xFFCCCCCC),
                                                                modifier = Modifier.size(22.dp)
                                                            )
                                                        }
                                                    }

                                                    // Single episode delete button overlay with shadow effect
                                                    if (isSingleVideo && isDeleteOverlayActive) {
                                                        Box(
                                                            modifier = Modifier
                                                                .matchParentSize()
                                                                .clip(RoundedCornerShape(6.dp))
                                                                .background(Color.Black.copy(alpha = 0.85f))
                                                                .clickable {
                                                                    group.episodes.firstOrNull()?.let { episodeToDelete = it }
                                                                    isDeleteOverlayActive = false
                                                                },
                                                            contentAlignment = Alignment.Center
                                                        ) {
                                                            Text(
                                                                text = "DELETE",
                                                                color = Color.White,
                                                                fontSize = 20.sp,
                                                                fontWeight = FontWeight.Black,
                                                                letterSpacing = 2.sp,
                                                                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                                                modifier = Modifier.padding(12.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }

                                            if (downloadedGroups.any { it.episodes.size == 1 }) {
                                                item {
                                                    Text(
                                                        text = "Hold card to delete single episode",
                                                        color = Color(0xFF6B7280),
                                                        fontSize = 11.sp,
                                                        textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .padding(top = 4.dp, bottom = 4.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                    }
                                }

                                // Delete Single Episode Dialog
                                if (episodeToDelete != null) {
                                    val target = episodeToDelete!!
                                    AlertDialog(
                                        onDismissRequest = { episodeToDelete = null },
                                        title = {
                                            Text(
                                                text = "Delete Episode",
                                                color = Color.White,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 17.sp
                                            )
                                        },
                                        text = {
                                            Text(
                                                text = "Delete Episode ${target.episodeNumber} (${formatDownloadedBytes(getDiskSizeForEpisode(target))}) from your storage?",
                                                color = Color(0xFFCCCCCC),
                                                fontSize = 13.5.sp
                                            )
                                        },
                                        confirmButton = {
                                            TextButton(
                                                onClick = {
                                                    coroutineScope.launch {
                                                        downloadManager.deleteEpisode(target.anilistId, target.episodeNumber)
                                                        storageStats = downloadManager.getStorageStats()
                                                        episodeToDelete = null
                                                        Toast.makeText(context, "Deleted Episode ${target.episodeNumber}", Toast.LENGTH_SHORT).show()
                                                    }
                                                }
                                            ) {
                                                Text("Delete", color = Color(0xFFFF5252), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        dismissButton = {
                                            TextButton(onClick = { episodeToDelete = null }) {
                                                Text("Cancel", color = Color(0xFF8E918F), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        containerColor = Color(0xFF141414),
                                        titleContentColor = Color.White,
                                        textContentColor = Color(0xFFCCCCCC),
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                }

                                // Delete Entire Series Dialog
                                if (groupToDelete != null) {
                                    val targetGroup = groupToDelete!!
                                    AlertDialog(
                                        onDismissRequest = { groupToDelete = null },
                                        title = {
                                            Text(
                                                text = "Delete Entire Series",
                                                color = Color.White,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 17.sp
                                            )
                                        },
                                        text = {
                                            Text(
                                                text = "Delete all ${targetGroup.episodes.size} downloaded episodes (${formatDownloadedBytes(targetGroup.totalSizeBytes)}) of ${targetGroup.animeTitle}?",
                                                color = Color(0xFFCCCCCC),
                                                fontSize = 13.5.sp
                                            )
                                        },
                                        confirmButton = {
                                            TextButton(
                                                onClick = {
                                                    coroutineScope.launch {
                                                        downloadManager.deleteAnimeGroup(targetGroup.anilistId)
                                                        storageStats = downloadManager.getStorageStats()
                                                        groupToDelete = null
                                                        selectedSeriesDrilldown = null
                                                        Toast.makeText(context, "Deleted ${targetGroup.animeTitle}", Toast.LENGTH_SHORT).show()
                                                    }
                                                }
                                            ) {
                                                Text("Delete All Episodes", color = Color(0xFFFF5252), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        dismissButton = {
                                            TextButton(onClick = { groupToDelete = null }) {
                                                Text("Cancel", color = Color(0xFF8E918F), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        containerColor = Color(0xFF141414),
                                        titleContentColor = Color.White,
                                        textContentColor = Color(0xFFCCCCCC),
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                }

                                // Delete All Downloads Dialog
                                if (showDeleteAllDownloadsDialog) {
                                    AlertDialog(
                                        onDismissRequest = { showDeleteAllDownloadsDialog = false },
                                        title = {
                                            Text(
                                                text = "Delete All Downloads",
                                                color = Color.White,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 17.sp
                                            )
                                        },
                                        text = {
                                            Text(
                                                text = "Are you sure you want to delete all downloaded anime episodes? This will permanently remove all offline files from your device storage.",
                                                color = Color(0xFFCCCCCC),
                                                fontSize = 13.5.sp,
                                                lineHeight = 19.sp
                                            )
                                        },
                                        confirmButton = {
                                            TextButton(
                                                onClick = {
                                                    coroutineScope.launch {
                                                        downloadManager.deleteAllDownloads()
                                                        storageStats = downloadManager.getStorageStats()
                                                        showDeleteAllDownloadsDialog = false
                                                        selectedSeriesDrilldown = null
                                                        Toast.makeText(context, "All downloads deleted", Toast.LENGTH_SHORT).show()
                                                    }
                                                }
                                            ) {
                                                Text("Delete All", color = Color(0xFFFF5252), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        dismissButton = {
                                            TextButton(onClick = { showDeleteAllDownloadsDialog = false }) {
                                                Text("Cancel", color = Color(0xFF8E918F), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        containerColor = Color(0xFF141414),
                                        titleContentColor = Color.White,
                                        textContentColor = Color(0xFFCCCCCC),
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                }

                                // Delete Subtitle Model Confirmation Dialog
                                modelToDelete?.let { model ->
                                    val sizeMb = model.sizeBytes / (1024 * 1024)
                                    AlertDialog(
                                        onDismissRequest = { modelToDelete = null },
                                        title = {
                                            Text(
                                                text = "Delete Subtitle model (${model.langName})?",
                                                color = Color.White,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 17.sp
                                            )
                                        },
                                        text = {
                                            Text(
                                                text = "Are you sure you want to delete Subtitle model (${model.langName}) (${sizeMb} MB)? You will need to download it again if you wish to translate subtitles into ${model.langName} offline.",
                                                color = Color(0xFFCCCCCC),
                                                fontSize = 13.5.sp,
                                                lineHeight = 19.sp
                                            )
                                        },
                                        confirmButton = {
                                            TextButton(
                                                onClick = {
                                                    com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.deleteModel(this@AnimeBoxMainActivity, model.langCode)
                                                    installedAiModels = com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.getInstalledModels(this@AnimeBoxMainActivity)
                                                    storageStats = downloadManager.getStorageStats()
                                                    modelToDelete = null
                                                    Toast.makeText(this@AnimeBoxMainActivity, "Subtitle model (${model.langName}) deleted", Toast.LENGTH_SHORT).show()
                                                }
                                            ) {
                                                Text("Delete Model", color = Color(0xFFFF5252), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        dismissButton = {
                                            TextButton(onClick = { modelToDelete = null }) {
                                                Text("Cancel", color = Color(0xFF8E918F), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        containerColor = Color(0xFF141414),
                                        titleContentColor = Color.White,
                                        textContentColor = Color(0xFFCCCCCC),
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                }

                                // Model Warning & Download Persona Dialogue UI
                                modelWarningPrompt?.let { modelInfo ->
                                    val sizeMb = modelInfo.sizeBytes / (1024 * 1024)
                                    val isSpeechModel = com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.JAPANESE_SPEECH_MODELS.any { it.langCode.equals(modelInfo.langCode, true) }

                                    Box(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .background(Color.Black.copy(alpha = 0.82f))
                                            .clickable(
                                                interactionSource = remember { MutableInteractionSource() },
                                                indication = null
                                            ) { modelWarningPrompt = null }
                                            .padding(horizontal = 20.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .widthIn(max = 520.dp)
                                                .clickable(
                                                    interactionSource = remember { MutableInteractionSource() },
                                                    indication = null
                                                ) {},
                                            verticalAlignment = Alignment.Bottom
                                        ) {
                                            // 1. Chibi Character with glowing spot shadow
                                            Box(
                                                modifier = Modifier
                                                    .size(76.dp)
                                                    .offset(y = 2.dp),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Image(
                                                    painter = painterResource(id = R.drawable.ic_thank_chibi),
                                                    contentDescription = "Chibi",
                                                    modifier = Modifier
                                                        .size(76.dp)
                                                        .shadow(12.dp, shape = CircleShape, spotColor = Color(0xFFFFB300)),
                                                    contentScale = ContentScale.Fit
                                                )
                                            }

                                            // 2. Speech Bubble Tail
                                            Canvas(
                                                modifier = Modifier
                                                    .size(14.dp, 20.dp)
                                                    .offset(x = 1.dp, y = (-18).dp)
                                            ) {
                                                val path = Path().apply {
                                                    moveTo(size.width, 0f)
                                                    lineTo(0f, size.height * 0.5f)
                                                    lineTo(size.width, size.height)
                                                    close()
                                                }
                                                drawPath(path, color = Color(0xF5141522))
                                                drawPath(
                                                    path,
                                                    color = Color(0xFFFFB300),
                                                    style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round)
                                                )
                                            }

                                            // 3. Persona Dialogue Bubble Body
                                            Column(
                                                modifier = Modifier
                                                    .weight(1f)
                                                    .clip(RoundedCornerShape(topStart = 4.dp, topEnd = 16.dp, bottomEnd = 16.dp, bottomStart = 16.dp))
                                                    .background(
                                                        Brush.linearGradient(
                                                            colors = listOf(
                                                                Color(0xF8151725),
                                                                Color(0xF20F101A)
                                                            )
                                                        )
                                                    )
                                                    .border(
                                                        width = 1.8.dp,
                                                        brush = Brush.horizontalGradient(
                                                            colors = listOf(
                                                                Color(0xFFFFB300),
                                                                Color(0xFFFF5722),
                                                                Color(0xFFFF4081)
                                                            )
                                                        ),
                                                        shape = RoundedCornerShape(topStart = 4.dp, topEnd = 16.dp, bottomEnd = 16.dp, bottomStart = 16.dp)
                                                    )
                                                    .padding(horizontal = 14.dp, vertical = 12.dp)
                                            ) {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                                        Box(
                                                            modifier = Modifier
                                                                .clip(RoundedCornerShape(8.dp))
                                                                .background(
                                                                    Brush.horizontalGradient(
                                                                        listOf(Color(0xFFFF9800), Color(0xFFFF5722))
                                                                    )
                                                                )
                                                                .padding(horizontal = 7.dp, vertical = 2.dp)
                                                        ) {
                                                            Text(
                                                                text = if (isSpeechModel) "AI SPEECH REQUIREMENT ⚡" else "AI TRANSLATION MODEL ⚡",
                                                                color = Color.White,
                                                                fontSize = 9.5.sp,
                                                                fontWeight = FontWeight.Black,
                                                                letterSpacing = 0.8.sp
                                                            )
                                                        }
                                                        Spacer(modifier = Modifier.width(8.dp))
                                                        Text(
                                                            text = modelInfo.langName,
                                                            color = Color(0xFFFFD54F),
                                                            fontSize = 12.sp,
                                                            fontWeight = FontWeight.Bold
                                                        )
                                                    }

                                                    Text(
                                                        text = "✕",
                                                        color = Color.White.copy(alpha = 0.6f),
                                                        fontSize = 13.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier.clickable { modelWarningPrompt = null }
                                                    )
                                                }

                                                Spacer(modifier = Modifier.height(8.dp))

                                                Text(
                                                    text = if (isSpeechModel) {
                                                        "On-device AI speech model (${modelInfo.langName}, ~$sizeMb MB) runs 100% locally on your phone's processor.\n\n⚠️ Requires high-end processor (Snapdragon 8 / Dimensity 8000+) & 6GB+ RAM for real-time inference without device warmth."
                                                    } else {
                                                        "On-device AI translation model (${modelInfo.langName}, ~$sizeMb MB) runs locally on your device.\n\n⚡ Once downloaded, live Japanese subtitle translation works at full speed 100% offline."
                                                    },
                                                    color = Color(0xFFF1F3FF),
                                                    fontSize = 11.5.sp,
                                                    lineHeight = 16.sp,
                                                    fontWeight = FontWeight.Medium
                                                )

                                                Spacer(modifier = Modifier.height(14.dp))

                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                                ) {
                                                    Button(
                                                        onClick = { modelWarningPrompt = null },
                                                        modifier = Modifier.weight(1f),
                                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0x2AFFFFFF)),
                                                        shape = RoundedCornerShape(8.dp)
                                                    ) {
                                                        Text("Cancel", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                                                    }
                                                    Button(
                                                        onClick = {
                                                            val target = modelInfo
                                                            modelWarningPrompt = null
                                                            coroutineScope.launch {
                                                                val success = com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.downloadModel(
                                                                    context = this@AnimeBoxMainActivity,
                                                                    langCode = target.langCode
                                                                )
                                                                if (success) {
                                                                    installedAiModels = com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.getInstalledModels(this@AnimeBoxMainActivity)
                                                                    if (isSpeechModel) {
                                                                        selectedSpeechCode = target.langCode
                                                                        com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.setSelectedSpeechModel(this@AnimeBoxMainActivity, target.langCode)
                                                                    }
                                                                }
                                                            }
                                                        },
                                                        modifier = Modifier.weight(1f),
                                                        colors = ButtonDefaults.buttonColors(containerColor = AnimeBoxThemeHelper.getPrimaryColor(this@AnimeBoxMainActivity)),
                                                        shape = RoundedCornerShape(8.dp)
                                                    ) {
                                                        Text("Download (~$sizeMb MB)", color = Color.Black, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }

                                // Delete Saved Subtitle Confirmation Dialog
                                subtitleToDelete?.let { targetSub ->
                                    val subKb = (targetSub.fileSizeBytes / 1024).coerceAtLeast(1)
                                    AlertDialog(
                                        onDismissRequest = { subtitleToDelete = null },
                                        title = {
                                            Text(
                                                text = "Delete Subtitle File?",
                                                color = Color.White,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 17.sp
                                            )
                                        },
                                        text = {
                                            Text(
                                                text = "Are you sure you want to delete ${targetSub.langName} subtitles for \"${targetSub.animeTitle}\" (Episode ${targetSub.episodeNum}, ${subKb} KB)? You can always re-translate it from the video player.",
                                                color = Color(0xFFCCCCCC),
                                                fontSize = 13.5.sp,
                                                lineHeight = 19.sp
                                            )
                                        },
                                        confirmButton = {
                                            TextButton(
                                                onClick = {
                                                    com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.deleteSavedSubtitle(this@AnimeBoxMainActivity, targetSub.filePath)
                                                    val updatedSubs = com.lagradost.cloudstream3.ui.animebox.api.AiSubtitleModelManager.getAllSavedSubtitles(this@AnimeBoxMainActivity)
                                                    savedSubtitles = updatedSubs
                                                    val remainingForAnime = updatedSubs.filter {
                                                        if (targetSub.anilistId > 0) it.anilistId == targetSub.anilistId else it.animeTitle == targetSub.animeTitle
                                                    }
                                                    if (remainingForAnime.isEmpty()) {
                                                        selectedSubtitleDrilldown = null
                                                    } else {
                                                        selectedSubtitleDrilldown = selectedSubtitleDrilldown?.copy(
                                                            subtitles = remainingForAnime.sortedBy { it.episodeNum },
                                                            totalSizeBytes = remainingForAnime.sumOf { it.fileSizeBytes }
                                                        )
                                                    }
                                                    subtitleToDelete = null
                                                    Toast.makeText(this@AnimeBoxMainActivity, "Subtitle deleted", Toast.LENGTH_SHORT).show()
                                                }
                                            ) {
                                                Text("Delete Subtitle", color = Color(0xFFFF5252), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        dismissButton = {
                                            TextButton(onClick = { subtitleToDelete = null }) {
                                                Text("Cancel", color = Color(0xFF8E918F), fontWeight = FontWeight.Bold)
                                            }
                                        },
                                        containerColor = Color(0xFF141414),
                                        titleContentColor = Color.White,
                                        textContentColor = Color(0xFFCCCCCC),
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                }

                                // Fullscreen Screenshot Lightbox Dialog
                                fullscreenScreenshotGallery?.let { (list, idx) ->
                                    ScreenshotLightboxDialog(
                                        screenshots = list,
                                        initialIndex = idx,
                                        onDismiss = { fullscreenScreenshotGallery = null },
                                        onDelete = { deletedItem ->
                                            try {
                                                deletedItem.file.delete()
                                                screenshotRefreshRevision++
                                            } catch (_: Exception) {}
                                        }
                                    )
                                }
                            }
    }
    }

    @Composable
    fun NetflixBottomNav(
        selectedTab: Int,
        onTabSelected: (Int) -> Unit,
        onMySpaceClick: () -> Unit
    ) {
        val context = androidx.compose.ui.platform.LocalContext.current
        val displayText: (String) -> String = { com.lagradost.cloudstream3.ui.animebox.settings.AnimeBoxUiText.text(context, it) }
        val profileRevision by ProfileManager.profileRevisionFlow.collectAsState()
        val activeProfId = remember(profileRevision) { ProfileManager.getActiveProfile(context) }
        val activeProfileObj = remember(profileRevision, activeProfId) {
            ProfileManager.getProfiles(context).find { it.id == activeProfId }
        }
        val activeName = activeProfileObj?.name ?: "Guest"
        val avatarUrl = activeProfileObj?.avatarUrl ?: ""
        val profilePainter = remember(avatarUrl) {
            if (avatarUrl.startsWith("android.resource://")) {
                val resName = avatarUrl.substringAfterLast("/")
                val resId = context.resources.getIdentifier(resName, "drawable", context.packageName)
                if (resId != 0) resId else avatarUrl
            } else {
                avatarUrl
            }
        }
        val themeRevision by AnimeBoxThemeHelper.themeRevisionFlow.collectAsState()
        val navBgColor = remember(themeRevision) { AnimeBoxThemeHelper.getNavbarBgColor(context) }
        val navOutlineColor = remember(themeRevision) { AnimeBoxThemeHelper.getNavbarOutlineColor(context) }

        Box(
            modifier = Modifier
                .fillMaxWidth()
                .navigationBarsPadding(),
            contentAlignment = Alignment.BottomCenter
        ) {
            // Background bar with sleek rounded top (no thin border outline)
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(60.dp)
                    .clip(RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp))
                    .background(navBgColor)
            )

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(60.dp),
                horizontalArrangement = Arrangement.SpaceAround,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Tab 0: Home (Monochrome theme: White for active, #9E9EA5 for inactive)
                val activeColor = Color.White
                val isHomeSelected = selectedTab == 0
                val homeColor = if (isHomeSelected) activeColor else Color(0xFF9E9EA5)
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center,
                    modifier = Modifier
                        .weight(1f)
                        .clickable(
                            interactionSource = remember { MutableInteractionSource() },
                            indication = null
                        ) { onTabSelected(0) }
                        .padding(horizontal = 4.dp, vertical = 2.dp)
                ) {
                    Icon(
                        imageVector = if (isHomeSelected) CustomHomeSmileAngleFilledIcon else CustomHomeSmileAngleOutlineIcon,
                        contentDescription = displayText("Home"),
                        tint = homeColor,
                        modifier = Modifier.size(24.5.dp)
                    )
                    Spacer(modifier = Modifier.height(3.dp))
                    Text(
                        text = displayText("Home"),
                        color = homeColor,
                        fontSize = 11.sp,
                        fontWeight = if (isHomeSelected) FontWeight.Bold else FontWeight.Medium
                    )
                }

                // Tab 1: Search
                val isSearchSelected = selectedTab == 1
                val searchColor = if (isSearchSelected) activeColor else Color(0xFF9E9EA5)
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center,
                    modifier = Modifier
                        .weight(1f)
                        .clickable(
                            interactionSource = remember { MutableInteractionSource() },
                            indication = null
                        ) { onTabSelected(1) }
                        .padding(horizontal = 4.dp, vertical = 2.dp)
                ) {
                    Icon(
                        imageVector = CustomSearchIcon,
                        contentDescription = displayText("Search"),
                        tint = searchColor,
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.height(3.dp))
                    Text(
                        text = displayText("Search"),
                        color = searchColor,
                        fontSize = 11.sp,
                        fontWeight = if (isSearchSelected) FontWeight.Bold else FontWeight.Medium
                    )
                }

                // Profile sits in middle - larger and naturally fills navbar without empty bottom space
                val isSpaceSelected = selectedTab == 4
                val decUrl = activeProfileObj?.decorationUrl ?: ""
                val hasAnimatedAvatar = (decUrl.isNotBlank() && !decUrl.equals("none", ignoreCase = true)) ||
                    avatarUrl.endsWith(".gif", ignoreCase = true) ||
                    avatarUrl.endsWith(".webp", ignoreCase = true) ||
                    avatarUrl.contains("animated", ignoreCase = true)

                Box(
                    modifier = Modifier
                        .weight(1f)
                        .clickable(
                            interactionSource = remember { MutableInteractionSource() },
                            indication = null
                        ) { onMySpaceClick() },
                    contentAlignment = Alignment.Center
                ) {
                    val profileBoxModifier = if (hasAnimatedAvatar) {
                        Modifier
                            .offset(y = (-5).dp)
                            .size(54.dp)
                            .clickable(
                                interactionSource = remember { MutableInteractionSource() },
                                indication = null
                            ) { onMySpaceClick() }
                    } else {
                        Modifier
                            .offset(y = (-5).dp)
                            .size(52.dp)
                            .shadow(10.dp, CircleShape)
                            .clip(CircleShape)
                            .background(navBgColor)
                            .border(2.5.dp, Color.White, CircleShape)
                            .padding(3.dp)
                            .clickable(
                                interactionSource = remember { MutableInteractionSource() },
                                indication = null
                            ) { onMySpaceClick() }
                    }

                    Box(
                        modifier = profileBoxModifier,
                        contentAlignment = Alignment.Center
                    ) {
                        com.lagradost.cloudstream3.ui.animebox.profiles.DecoratedProfilePicture(
                            avatarUrl = avatarUrl,
                            decorationUrl = decUrl,
                            size = if (hasAnimatedAvatar) 54.dp else 44.dp,
                            fallbackInitial = activeName,
                            forceCircle = true
                        )
                    }
                }

                // Tab 2: Downloads
                val isDownloadsSelected = selectedTab == 2
                val downloadsColor = if (isDownloadsSelected) activeColor else Color(0xFF9E9EA5)
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center,
                    modifier = Modifier
                        .weight(1f)
                        .clickable(
                            interactionSource = remember { MutableInteractionSource() },
                            indication = null
                        ) { onTabSelected(2) }
                        .padding(horizontal = 4.dp, vertical = 2.dp)
                ) {
                    Icon(
                        imageVector = if (isDownloadsSelected) CustomDownloadsNavbarBoldIcon else CustomDownloadsNavbarIcon,
                        contentDescription = "Downloads",
                        tint = downloadsColor,
                        modifier = Modifier.size(25.dp)
                    )
                    Spacer(modifier = Modifier.height(3.dp))
                    Text(
                        text = "Downloads",
                        color = downloadsColor,
                        fontSize = 11.sp,
                        fontWeight = if (isDownloadsSelected) FontWeight.Bold else FontWeight.Medium
                    )
                }

                // Tab 3: My Lists
                val isListSelected = selectedTab == 3
                val listColor = if (isListSelected) activeColor else Color(0xFF9E9EA5)
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center,
                    modifier = Modifier
                        .weight(1f)
                        .clickable(
