    @Composable
    fun NotificationsDialog(
        notifications: List<SupabaseNotification>,
        onDismiss: () -> Unit,
        onMarkAllAsRead: () -> Unit,
        onNotificationClick: (SupabaseNotification) -> Unit,
        onClearAll: () -> Unit
    ) {
        val primaryColor = MaterialTheme.colorScheme.primary
        Dialog(
            onDismissRequest = onDismiss,
            properties = DialogProperties(usePlatformDefaultWidth = false)
        ) {
            val view = androidx.compose.ui.platform.LocalView.current
            DisposableEffect(view) {
                var parent = view.parent
                while (parent != null) {
                    if (parent is android.app.Dialog) {
                        parent.window?.clearFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND)
                        break
                    }
                    parent = parent.parent
                }
                onDispose {}
            }

            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clickable(
                        interactionSource = remember { MutableInteractionSource() },
                        indication = null
                    ) { onDismiss() },
                contentAlignment = Alignment.TopCenter
            ) {
                // Floating Card anchored near top matching user reference design
                Box(
                    modifier = Modifier
                        .padding(top = 52.dp, start = 16.dp, end = 16.dp)
                        .widthIn(min = 320.dp, max = 390.dp)
                        .wrapContentHeight()
                        .clip(RoundedCornerShape(14.dp))
                        .background(Color(0xFF141416))
                        .clickable(
                            interactionSource = remember { MutableInteractionSource() },
                            indication = null
                        ) { /* Consume clicks inside card */ }
                ) {
                    Column(modifier = Modifier.fillMaxWidth()) {
                        // Top Header Bar
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFF18181B))
                                .padding(horizontal = 16.dp, vertical = 14.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "Notifications",
                                color = Color.White,
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold
                            )

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(14.dp)
                            ) {
                                if (notifications.isNotEmpty()) {
                                    Text(
                                        text = "Mark all read",
                                        color = Color.White,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .clickable { onMarkAllAsRead() }
                                            .padding(horizontal = 4.dp, vertical = 2.dp)
                                    )

                                    Text(
                                        text = "Clear all",
                                        color = Color.White,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .clickable { onClearAll() }
                                            .padding(horizontal = 4.dp, vertical = 2.dp)
                                    )
                                }
                            }
                        }

                        Spacer(modifier = Modifier.fillMaxWidth().height(1.dp).background(Color(0xFF27272A)))

                        // Notifications list
                        if (notifications.isEmpty()) {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 36.dp, horizontal = 20.dp),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Center
                            ) {
                                Icon(
                                    imageVector = CustomNotificationIcon,
                                    contentDescription = null,
                                    tint = Color(0xFF52525B),
                                    modifier = Modifier.size(32.dp)
                                )
                                Spacer(modifier = Modifier.height(10.dp))
                                Text(
                                    text = "No notifications yet",
                                    color = Color(0xFFA1A1AA),
                                    fontSize = 13.5.sp,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "New episodes and announcements will appear here",
                                    color = Color(0xFF71717A),
                                    fontSize = 12.sp,
                                    textAlign = TextAlign.Center
                                )
                            }
                        } else {
                            LazyColumn(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .heightIn(max = 480.dp)
                            ) {
                                items(notifications.size) { index ->
                                    val notif = notifications[index]
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(if (!notif.isRead) Color(0xFF1C1C20) else Color.Transparent)
                                            .clickable { onNotificationClick(notif) }
                                            .padding(horizontal = 16.dp, vertical = 14.dp)
                                    ) {
                                        // Title & Unread indicator
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = notif.title,
                                                color = Color.White,
                                                fontSize = 14.5.sp,
                                                fontWeight = FontWeight.Bold,
                                                lineHeight = 19.sp,
                                                modifier = Modifier.weight(1f)
                                            )
                                            if (!notif.isRead) {
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Box(
                                                    modifier = Modifier
                                                        .size(7.5.dp)
                                                        .background(Color.White, CircleShape)
                                                )
                                            }
                                        }

                                        // Message Body
                                        if (notif.message.isNotEmpty()) {
                                            Spacer(modifier = Modifier.height(6.dp))
                                            Text(
                                                text = notif.message,
                                                color = Color(0xFFA1A1AA),
                                                fontSize = 13.sp,
                                                lineHeight = 18.sp
                                            )
                                        }

                                        // Image / GIF attachment preview
                                        if (!notif.imageUrl.isNullOrEmpty()) {
                                            Spacer(modifier = Modifier.height(10.dp))
                                            Box(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .heightIn(max = 160.dp)
                                                    .clip(RoundedCornerShape(8.dp))
                                                    .background(Color(0xFF09090B))
                                                    .border(1.dp, Color(0xFF27272A), RoundedCornerShape(8.dp))
                                            ) {
                                                Image(
                                                    painter = rememberAsyncImagePainter(model = notif.imageUrl),
                                                    contentDescription = "Notification Image",
                                                    contentScale = ContentScale.Crop,
                                                    modifier = Modifier.fillMaxSize()
                                                )
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(8.dp))

                                        // Timestamp & Optional View action
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = notif.formattedDateTime(),
                                                color = Color(0xFF71717A),
                                                fontSize = 11.5.sp
                                            )

                                            if (!notif.link.isNullOrEmpty()) {
                                                Text(
                                                    text = "Open →",
                                                    color = primaryColor,
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }
                                    }

                                    if (index < notifications.size - 1) {
                                        Spacer(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(1.dp)
                                                .background(Color(0xFF202024))
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    @Composable
    fun FaqSection() {
        val context = androidx.compose.ui.platform.LocalContext.current
        val faqs = remember {
            listOf(
                "What is FireFly?" to "FireFly is a premium streaming service that allows you to watch a wide variety of anime shows, movies, and more on thousands of internet-connected devices.",
                "How much does FireFly Cost?" to "FireFly is completely free! There are no hidden fees, subscriptions, or contracts.",
                "Where can I watch?" to "Watch anywhere, anytime. Sign in with your account to watch instantly on your phone or tablet.",
                "How do I cancel?" to "Since FireFly is free, there are no subscriptions to cancel! You can simply close or uninstall the app at any time.",
                "What can I watch on FireFly?" to "FireFly has an extensive library of anime feature films, documentaries, TV shows, and award-winning FireFly originals. Watch as much as you want, anytime you want.",
                "Is FireFly good for kids?" to "Yes! You can create dedicated kids profiles to filter out adult content and restrict viewing to age-appropriate anime content."
            )
        }

        var expandedIndex by remember { mutableStateOf(-1) }

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 24.dp)
        ) {
            Text(
                text = com.lagradost.cloudstream3.ui.animebox.settings.AnimeBoxUiText.text(context, "Frequently Asked Questions"),
                fontSize = 20.sp,
                fontWeight = FontWeight.Bold,
                color = Color.White,
                modifier = Modifier.padding(bottom = 16.dp)
            )

            faqs.forEachIndexed { index, faq ->
                val isExpanded = expandedIndex == index
                FaqItem(
                    question = faq.first,
                    answer = faq.second,
                    isExpanded = isExpanded,
                    onToggle = {
                        expandedIndex = if (isExpanded) -1 else index
                    }
                )
                Spacer(modifier = Modifier.height(8.dp))
            }
        }
    }

    @Composable
    fun FaqItem(question: String, answer: String, isExpanded: Boolean, onToggle: () -> Unit) {
        val rotationAngle by androidx.compose.animation.core.animateFloatAsState(
            targetValue = if (isExpanded) 45f else 0f,
            label = "plus_icon_rotation"
        )

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(8.dp))
                .background(Color(0xFF2D2D2D))
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { onToggle() }
                    .padding(horizontal = 16.dp, vertical = 18.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = question,
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Medium,
                    color = Color.White,
                    modifier = Modifier.weight(1f)
                )
                Icon(
                    imageVector = Icons.Default.Add,
                    contentDescription = "Expand",
                    tint = Color.White,
                    modifier = Modifier
                        .size(24.dp)
                        .rotate(rotationAngle)
                )
            }

            if (isExpanded) {
                Spacer(modifier = Modifier.fillMaxWidth().height(1.dp).background(Color.Black))
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = answer,
                        fontSize = 14.sp,
                        color = Color.LightGray,
                        lineHeight = 20.sp
                    )
                }
            }
        }
    }

    @Composable
    fun HomeGenreCard(genre: HomeGenreCategory, onClick: () -> Unit) {
        var backdropUrl by remember(genre.id, genre.backdropUrl) { mutableStateOf(genre.backdropUrl.ifEmpty { genre.posterUrl }) }
        LaunchedEffect(genre.anilistId, genre.backdropUrl) {
            if (genre.backdropUrl.isEmpty()) {
                try {
                    val tmdb = AniZipClient.getAnimeBackdropUrl(genre.anilistId)
                    if (tmdb.isNotEmpty()) {
                        backdropUrl = tmdb
                    }
                } catch (_: Exception) {}
            }
        }

        Box(
            modifier = Modifier
                .width(160.dp)
                .height(76.dp)
                .clip(RoundedCornerShape(8.dp))
                .background(genre.startColor)
                .clickable { onClick() }
        ) {
            // Right-side Backdrop Image with center portion visible on right
            if (backdropUrl.isNotEmpty()) {
                Image(
                    painter = rememberAsyncImagePainter(model = backdropUrl),
                    contentDescription = genre.displayName,
                    contentScale = ContentScale.Crop,
                    alignment = Alignment.Center,
                    modifier = Modifier
                        .fillMaxHeight()
                        .width(96.dp)
                        .align(Alignment.CenterEnd)
                        .clip(RoundedCornerShape(topEnd = 8.dp, bottomEnd = 8.dp))
                )
            }

            // Organic curved wave mask & horizontal smooth blend
            androidx.compose.foundation.Canvas(modifier = Modifier.fillMaxSize()) {
                val w = size.width
                val h = size.height

                val path = androidx.compose.ui.graphics.Path().apply {
                    moveTo(0f, 0f)
                    lineTo(w * 0.44f, 0f)
                    cubicTo(
                        w * 0.56f, h * 0.35f,
                        w * 0.38f, h * 0.65f,
                        w * 0.48f, h
                    )
                    lineTo(0f, h)
                    close()
                }
                drawPath(path = path, color = genre.startColor)

                drawRect(
                    brush = Brush.horizontalGradient(
                        colorStops = arrayOf(
                            0.0f to genre.startColor,
                            0.42f to genre.startColor,
                            0.58f to genre.startColor.copy(alpha = 0.85f),
                            0.78f to genre.startColor.copy(alpha = 0.20f),
                            1.0f to Color.Transparent
                        )
                    )
                )
            }

            // Genre Title (Bold clean white text)
            Text(
                text = genre.displayName,
                color = Color.White,
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                style = TextStyle(
                    shadow = androidx.compose.ui.graphics.Shadow(
                        color = Color.Black.copy(alpha = 0.90f),
                        blurRadius = 8f,
                        offset = androidx.compose.ui.geometry.Offset(0f, 2f)
                    )
                ),
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier
                    .align(Alignment.CenterStart)
                    .padding(start = 12.dp, end = 68.dp)
            )
        }
    }

    @Composable
    fun StudioPosterCard(
        studio: com.lagradost.cloudstream3.ui.animebox.api.StudioCardItem,
        onClick: () -> Unit
    ) {
        val interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }
        val isPressed by interactionSource.collectIsPressedAsState()
        val scale by androidx.compose.animation.core.animateFloatAsState(
            targetValue = if (isPressed) 0.96f else 1.0f,
            label = "studio_card_scale"
        )

        val studioFontFamily = cachedStudioFontFamily
        val studioColor = Color(studio.themeColor)
        var cardPosterUrl by remember(studio.name, studio.posterUrl) { mutableStateOf(studio.posterUrl) }
        var cardAnimeTitle by remember(studio.name, studio.popularAnimeTitle) { mutableStateOf(studio.popularAnimeTitle) }

        LaunchedEffect(studio.name, studio.isAdultStudio) {
            if (!studio.isAdultStudio || cardPosterUrl.isNotBlank()) return@LaunchedEffect
            val preferredMedia = if (studio.popularAnimeTitle.isNotBlank() && studio.popularAnimeTitle != "Popular Adult Releases") {
                runCatching {
                    val response = AniListClient.searchAnime(studio.popularAnimeTitle) ?: return@runCatching null
                    val root = JSONObject(response)
                    val nodes = root.optJSONObject("data")?.optJSONObject("Page")?.optJSONArray("media")
                    val preferred = studio.popularAnimeTitle.lowercase().replace(Regex("[^a-z0-9]+"), " ").trim()
                    (0 until (nodes?.length() ?: 0)).asSequence()
                        .mapNotNull { nodes?.optJSONObject(it) }
                        .firstOrNull { media ->
                            val titles = media.optJSONObject("title")
                            listOf(titles?.optString("english"), titles?.optString("romaji"), titles?.optString("native"))
                                .filterNotNull().any { title -> title.lowercase().replace(Regex("[^a-z0-9]+"), " ").trim() == preferred }
                        }
                }.getOrNull()
            } else null
            val response = runCatching { AniListClient.getAnimeByStudio(studio.queryName, 1) }.getOrNull()
            val studioMedia = runCatching {
                val root = JSONObject(response ?: return@runCatching null)
                root.optJSONObject("data")?.optJSONObject("Studio")
                    ?.optJSONObject("media")?.optJSONArray("nodes")?.let { nodes ->
                        val mediaItems = (0 until nodes.length()).asSequence()
                            .mapNotNull { nodes.optJSONObject(it) }
                            .filter { media -> media.optJSONObject("coverImage")?.optString("large").orEmpty().isNotBlank() }
                            .toList()
                        val preferred = studio.popularAnimeTitle
                            .lowercase()
                            .replace(Regex("[^a-z0-9]+"), " ")
                            .trim()
                        mediaItems.firstOrNull { media ->
                            val titles = media.optJSONObject("title")
                            listOf(titles?.optString("english"), titles?.optString("romaji"), titles?.optString("native"))
                                .filterNotNull()
                                .any { title ->
                                    val normalized = title.lowercase().replace(Regex("[^a-z0-9]+"), " ").trim()
                                    preferred.isNotBlank() && preferred != "popular adult releases" &&
                                        (normalized == preferred || normalized.contains(preferred) || preferred.contains(normalized))
                                }
                        } ?: mediaItems.firstOrNull()
                    }
            }.getOrNull()
            val firstMedia = preferredMedia ?: studioMedia
            firstMedia?.let { media ->
                val cover = media.optJSONObject("coverImage")?.optString("extraLarge").orEmpty()
                    .ifBlank { media.optJSONObject("coverImage")?.optString("large").orEmpty() }
                if (cover.isNotBlank()) cardPosterUrl = cover
                val title = media.optJSONObject("title")?.optString("english").orEmpty()
                    .ifBlank { media.optJSONObject("title")?.optString("romaji").orEmpty() }
                if (title.isNotBlank()) cardAnimeTitle = title
            }
        }

        Box(
            modifier = Modifier
                .width(118.dp)
                .height(174.dp)
                .scale(scale)
                .clip(RoundedCornerShape(8.dp))
                .background(Color(0xFF1B1B1F))
                .clickable(
                    interactionSource = interactionSource,
                    indication = null
                ) { onClick() }
        ) {
            // Adult studio artwork is resolved from each studio's current AniList releases.
            if (cardPosterUrl.isNotBlank()) {
                Image(
                    painter = rememberAsyncImagePainter(model = cardPosterUrl),
                    contentDescription = "$cardAnimeTitle — ${studio.name}",
                    contentScale = ContentScale.Crop,
                    alignment = Alignment.Center,
                    modifier = Modifier.fillMaxSize()
                )
            } else if (studio.isAdultStudio) {
                Image(
                    painter = painterResource(R.drawable.ic_hentai_bunny_raster),
                    contentDescription = studio.name,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier.fillMaxSize().padding(24.dp).alpha(0.35f)
                )
            }

            // Colorful Genre-Style Bottom Shadow & Vignette
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0.0f to Color.Transparent,
                                0.40f to Color.Transparent,
                                0.65f to studioColor.copy(alpha = 0.40f),
                                0.82f to studioColor.copy(alpha = 0.75f),
                                1.0f to studioColor.copy(alpha = 0.95f)
                            )
                        )
                    )
            )

            // Dark grounding gradient behind text for ultra-crisp legibility
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(65.dp)
                    .align(Alignment.BottomCenter)
                    .background(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0.0f to Color.Transparent,
                                0.5f to Color.Black.copy(alpha = 0.35f),
                                1.0f to Color.Black.copy(alpha = 0.75f)
                            )
                        )
                    )
            )

            // Typography matching Screenshot 1: Studio Name + COLLECTION subtext
            Column(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .fillMaxWidth()
                    .padding(horizontal = 6.dp, vertical = 8.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                                                Text(
                    text = studio.name.uppercase(),
                    color = Color.White,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold,
                    fontFamily = studioFontFamily,
                    letterSpacing = 0.8.sp,
                    lineHeight = 16.sp,
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    style = TextStyle(
                        shadow = androidx.compose.ui.graphics.Shadow(
                            color = Color.Black.copy(alpha = 0.95f),
                            offset = androidx.compose.ui.geometry.Offset(0f, 2f),
                            blurRadius = 4f
                        )
                    )
                )


                Spacer(modifier = Modifier.height(3.dp))
                Text(
                    text = "COLLECTION",
                    color = Color.White.copy(alpha = 0.75f),
                    fontSize = 8.sp,
                    fontWeight = FontWeight.Bold,
                    fontFamily = studioFontFamily,
                    letterSpacing = 2.0.sp,
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    style = TextStyle(
                        shadow = androidx.compose.ui.graphics.Shadow(
                            color = Color.Black,
                            offset = androidx.compose.ui.geometry.Offset(0f, 1f),
                            blurRadius = 2f
                        )
                    )
                )
            }
        }
    }

