                    "save_changes" -> "Save Changes"
                    "delete_profile" -> "Delete Profile"
                    "delete_confirm_title" -> "Delete Profile?"
                    "delete_confirm_msg" -> "Are you sure you want to delete this profile? This action cannot be undone."
                    "cancel" -> "Cancel"
                    "delete" -> "Delete"
                    "close" -> "Close"
                    "done" -> "Done"
                    "style_presets" -> "Style Presets"
                    "font_size" -> "Font Size"
                    "text_color" -> "Text Color"
                    "background_opacity" -> "Background Opacity"
                    "outline_thickness" -> "Outline Thickness"
                    "choose_theme" -> "Choose Theme Color"
                    "default_audio_sub" -> "Default Audio & Subtitles"
                    "preferred_audio" -> "Preferred Audio Track"
                    "preferred_sub" -> "Preferred Subtitle Track"
                    "auto_resume" -> "Auto-Resume Playback"
                    "auto_resume_sub" -> "Automatically resume episodes from where you left off"
                    else -> key
                }
            }
        }

        val galleryLauncher = rememberLauncherForActivityResult(
            contract = ActivityResultContracts.GetContent()
        ) { uri: Uri? ->
            if (uri != null) {
                try {
                    context.contentResolver.takePersistableUriPermission(
                        uri,
                        Intent.FLAG_GRANT_READ_URI_PERMISSION
                    )
                } catch (e: Exception) {
                    e.printStackTrace()
                }
                val uriStr = uri.toString()
                editProfileAvatarUrl = uriStr

                // Auto-save immediately so the icon updates instantly everywhere
                val p = editingProfile
                if (p != null) {
                    val profiles = ProfileManager.getProfiles(context).toMutableList()
                    val targetIdx = profiles.indexOfFirst { it.id == p.id }
                    if (targetIdx != -1) {
                        val updated = UserProfile(p.id, editProfileName.trim().ifEmpty { p.name }, uriStr)
                        profiles[targetIdx] = updated
                        ProfileManager.saveProfiles(context, profiles)
                        editingProfile = updated
                        profilesList = ProfileManager.getProfiles(context)
                        onProfileSelected(p.id)
                    }
                }
            }
        }

        // Backup SAF Launchers
        val exportLauncher = rememberLauncherForActivityResult(
            contract = ActivityResultContracts.CreateDocument("application/json")
        ) { uri ->
            if (uri != null) {
                try {
                    val jsonData = com.lagradost.cloudstream3.ui.animebox.settings.AnimeBoxSettings.exportDataToJson(context)
                    context.contentResolver.openOutputStream(uri)?.use { outputStream ->
                        outputStream.write(jsonData.toByteArray(Charsets.UTF_8))
                    }
                    Toast.makeText(context, "Backup exported successfully!", Toast.LENGTH_LONG).show()
                } catch (e: Exception) {
                    Toast.makeText(context, "Export failed: ${e.localizedMessage}", Toast.LENGTH_LONG).show()
                }
            }
        }

        val importLauncher = rememberLauncherForActivityResult(
            contract = ActivityResultContracts.GetContent()
        ) { uri ->
            if (uri != null) {
                try {
                    val stringBuilder = java.lang.StringBuilder()
                    context.contentResolver.openInputStream(uri)?.use { inputStream ->
                        java.io.BufferedReader(java.io.InputStreamReader(inputStream)).use { reader ->
                            var line: String? = reader.readLine()
                            while (line != null) {
                                stringBuilder.append(line)
                                line = reader.readLine()
                            }
                        }
                    }
                    val jsonContent = stringBuilder.toString()
                    val result = com.lagradost.cloudstream3.ui.animebox.settings.AnimeBoxSettings.importDataFromJson(context, jsonContent)
                    if (result.isSuccess) {
                        profilesList = ProfileManager.getProfiles(context)
                        currentTheme = com.lagradost.cloudstream3.ui.animebox.settings.AnimeBoxSettings.getAppTheme(context)
                        Toast.makeText(context, "All app data and profiles restored successfully!", Toast.LENGTH_LONG).show()
                    } else {
                        Toast.makeText(context, "Import failed: ${result.exceptionOrNull()?.message}", Toast.LENGTH_LONG).show()
                    }
                } catch (e: Exception) {
                    Toast.makeText(context, "Error reading backup file: ${e.localizedMessage}", Toast.LENGTH_LONG).show()
                }
            }
        }

        @Composable
        fun SelectorBody() {
            var showNewsFeedScreen by remember { mutableStateOf(false) }
            var showAnimeGamesScreen by remember { mutableStateOf(false) }
            var showAppUsageScreen by remember { mutableStateOf(false) }

            if (showAppUsageScreen) {
                androidx.activity.compose.BackHandler {
                    showAppUsageScreen = false
                }
                com.lagradost.cloudstream3.ui.animebox.usage.AnimeWatchUsageScreen(
                    activeProfileId = editingProfile?.id,
                    onClose = { showAppUsageScreen = false },
                    onOpenAnimeDetails = { anilistId ->
                        showAppUsageScreen = false
                        openDetailsPage(anilistId, null)
                    }
                )
                return
            }

            if (showAnimeGamesScreen) {
                androidx.activity.compose.BackHandler {
                    showAnimeGamesScreen = false
                }
                com.lagradost.cloudstream3.ui.animebox.games.AnimeGamesScreen(
                    onClose = { showAnimeGamesScreen = false }
                )
                return
            }

            if (showNewsFeedScreen) {
                androidx.activity.compose.BackHandler {
                    showNewsFeedScreen = false
                }
                com.lagradost.cloudstream3.ui.animebox.news.AnimeBoxNewsFeedView(
                    onClose = { showNewsFeedScreen = false }
                )
                return
