@Composable
fun AnimeBoxHomeSkeletonLoading(modifier: Modifier = Modifier) {
    val infiniteTransition = rememberInfiniteTransition(label = "home_skeleton")
    val alpha by infiniteTransition.animateFloat(
        initialValue = 0.22f,
        targetValue = 0.58f,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis = 850, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "alpha"
    )
    val shimmerColor = Color(0xFF23242B).copy(alpha = alpha)

    Column(
        modifier = modifier
            .fillMaxSize()
            .background(Color.Black)
            .verticalScroll(rememberScrollState())
    ) {
        // 1. Netflix Spotlight Hero Banner Skeleton
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(380.dp)
                .background(shimmerColor)
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        Brush.verticalGradient(
                            colors = listOf(
                                Color.Transparent,
                                Color(0x60000000),
                                Color(0xFF000000)
                            )
                        )
                    )
            )
            Column(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 20.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Box(
                    modifier = Modifier
                        .width(180.dp)
                        .height(22.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(shimmerColor)
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Box(modifier = Modifier.width(60.dp).height(20.dp).clip(RoundedCornerShape(8.dp)).background(shimmerColor))
                    Box(modifier = Modifier.width(70.dp).height(20.dp).clip(RoundedCornerShape(8.dp)).background(shimmerColor))
                    Box(modifier = Modifier.width(65.dp).height(20.dp).clip(RoundedCornerShape(8.dp)).background(shimmerColor))
                }
                Row(
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.padding(top = 6.dp)
                ) {
                    Box(modifier = Modifier.width(120.dp).height(40.dp).clip(RoundedCornerShape(6.dp)).background(shimmerColor))
                    Box(modifier = Modifier.width(120.dp).height(40.dp).clip(RoundedCornerShape(6.dp)).background(shimmerColor))
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // 2. Continue Watching Section Skeleton
        Column(
            modifier = Modifier.fillMaxWidth().padding(start = 16.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Box(modifier = Modifier.width(140.dp).height(18.dp).clip(RoundedCornerShape(8.dp)).background(shimmerColor))
            Row(
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                repeat(3) {
                    Box(
                        modifier = Modifier
                            .width(215.dp)
                            .height(120.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(shimmerColor)
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(24.dp))

        // 3. Trending Now Poster Cards Skeleton
        Column(
            modifier = Modifier.fillMaxWidth().padding(start = 16.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Box(modifier = Modifier.width(120.dp).height(18.dp).clip(RoundedCornerShape(8.dp)).background(shimmerColor))
            Row(
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                repeat(4) {
                    Box(
                        modifier = Modifier
                            .width(115.dp)
                            .height(170.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(shimmerColor)
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(24.dp))
    }
}

